      "content": "from __future__ import annotations\n\nimport shutil\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nfrom vockpit.diagrams import Diagram\n\n\ndef escape_d2(s: str) -> str:\n    s = s.replace(\"\\r\\n\", \" \").replace(\"\\n\", \" \").replace(\"\\r\", \" \")\n    s = s.replace(\"\\\\\", \"\\\\\\\\\").replace('\"', '\\\\\"')\n    return s\n\n\ndef node_key(node_id: str) -> str:\n    return f\"n_{node_id.replace('-', '_')}\"\n\n\ndef render(diagram: Diagram) -> str:\n    lines: list[str] = [\n        \"# GENERATED by vockpit 0.1.0 from model/. Do not edit.\",\n        \"direction: right\",\n        \"\",\n        f\"title: |md # {diagram.title} | {{ near: top-center }}\",\n        \"\",\n        \"classes: {\",\n        \"  system:    { style: { stroke-width: 3; border-radius: 6 } }\",\n        \"  inner:     { style: { border-radius: 6 } }\",\n        \"  external:  { style: { stroke-dash: 4; border-radius: 6 } }\",\n        '  neighbour: { style: { stroke-dash: 4; border-radius: 6; fill: \"#eeeeee\" } }',\n        \"}\",\n        \"\",\n    ]\n\n    for node in diagram.nodes:\n        n_id = node_key(node.id)\n        escaped_title = escape_d2(node.title)\n        lines.append(f'{n_id}: \"{escaped_title}\" {{')\n\n        if node.role == \"person\":\n            lines.append(\"  shape: person\")\n        else:\n            lines.append(f\"  class: {node.role}\")\n\n        if node.link:\n            lines.append(f'  link: \"{node.link}\"')\n\n        if node.summary:\n            escaped_summary = escape_d2(node.summary)\n            lines.append(f'  tooltip: \"{escaped_summary}\"')\n\n        lines.append(\"}\")\n\n    if diagram.edges:\n        lines.append(\"\")\n        for edge in diagram.edges:\n            f_key = node_key(edge.from_id)\n            t_key = node_key(edge.to_id)\n            escaped_label = escape_d2(edge.label)\n            lines.append(f'{f_key} -> {t_key}: \"{escaped_label}\"')\n\n    lines.append(\"\")\n    return \"\\n\".join(lines)\n\n\ndef find_d2_executable() -> str | None:\n    found = shutil.which(\"d2\")\n    if found:\n        return found\n\n    # Development fallback\n    candidate = Path.home() / \"bin\" / (\"d2.exe\" if sys.platform == \"win32\" else \"d2\")\n    if candidate.is_file():\n        return str(candidate)\n\n    return None\n\n\ndef to_svg(d2_path: Path | str, svg_path: Path | str, d2_bin: str | None = None) -> None:\n    bin_path = d2_bin or find_d2_executable()\n    if not bin_path:\n        raise FileNotFoundError(\n            \"d2 not found on PATH. Install from https://d2lang.com or use --no-svg.\"\n        )\n\n    # Fixed argv, no shell; bin_path is the resolved d2 executable.\n    subprocess.run(  # noqa: S603\n        [bin_path, str(d2_path), str(svg_path)],\n        check=True,\n        capture_output=True,\n        text=True,\n    )\n",
